#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# REHEARSAL of the Production baseline cutover on a SCRATCH copy of Production.
# Same steps as prod-baseline-wizard.sh (revert history, mark baseline applied, push catch-up),
# but refuses Production and Staging URIs. Restore a Production backup / PITR point into a
# scratch Supabase project first (Dashboard -> Database -> Backups -> Restore to a new project).
# Run from the repo root:  bash schema/prod-rehearsal-wizard.sh
# Safe to repeat: restore a fresh copy each time. Never run the Production wizard until this is green.

TOTAL_STAGES=11

ENV_FILE=/dev/null   # never persist the DB URL anywhere
PROD_REF="zvoijyneresvkadpprel"
STAGING_REF="mzjsuvatrzhciojmbbbm"
BASELINE=20261009000000
EXPECTED_PUSH="20261009000100 20261013120000"
SNAPSHOT_SCHEMA="schema/prod-schema.sql"
STAGING_SNAPSHOT="schema/staging-schema.sql"

[[ -d supabase/migrations && -f supabase/migrations/${BASELINE}_production_baseline.sql ]] || { echo "Run this from the aios repo root."; exit 1; }
command -v psql >/dev/null || { echo "psql is required."; exit 1; }

LOG_DIR="schema/wizard-logs/rehearsal-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$LOG_DIR"

sql() { psql "$DB_URL" -v ON_ERROR_STOP=1 -X -At -c "$1"; }

run() {
  local log="$LOG_DIR/$1"; shift
  local shown="$*"; shown="${shown//"$DB_URL"/\$DB_URL}"
  note "\$ ${shown:0:200}"
  set +e
  "$@" 2>&1 | tee "$log"
  local rc=${PIPESTATUS[0]}
  set -e
  return "$rc"
}

abort() { printf '\n  %s✗ %s%s\n  Logs: %s\n' "$RED" "$1" "$RESET" "$LOG_DIR"; exit 1; }

banner "AIOS baseline REHEARSAL on a scratch copy of Production"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Confirm this is a scratch copy"
warn "This WRITES to the database you connect to. It must be a restored COPY of Production."
confirm "Is the target a scratch project restored from a Production backup / PITR point?" || abort "Restore a copy first."
confirm "Is the backup recent enough to reflect Production's current schema and history?" || abort "Restore a fresh copy."

step "Dashboard -> the SCRATCH project -> Settings -> Database -> Connect -> Session pooler (port 5432)."
ask_secret DB_URL "Paste the SCRATCH connection URI (hidden):"
[[ "$DB_URL" != *"$PROD_REF"* ]] || abort "That is the PRODUCTION URI. Use the scratch copy."
[[ "$DB_URL" != *"$STAGING_REF"* ]] || abort "That is the STAGING URI. Use the scratch copy."
[[ "$DB_URL" != *":6543"* ]] || abort "Transaction pooler (6543). Use the session pooler (5432)."
sql "select 1" >/dev/null || abort "Could not connect."
[[ "$(sql "select to_regclass('environment_sync.safety') is null")" == t ]] \
  || abort "environment_sync.safety exists: this looks like a Staging-derived copy, not Production."
[[ "$(sql "select count(*) > 0 from supabase_migrations.schema_migrations")" == t ]] \
  || abort "No migration history: this is not a restored Production copy."
say "History rows: $(sql 'select count(*) from supabase_migrations.schema_migrations')   latest: $(sql 'select max(version) from supabase_migrations.schema_migrations')"
pause

# ── 1b ────────────────────────────────────────────────────────────────────
stage "Deactivate cron jobs on the copy"
warn "A restored copy keeps its pg_cron jobs. They could send messages or sync from the scratch project."
ACTIVE=$(sql "select count(*) from cron.job where active" 2>/dev/null || echo "?")
say "Active cron jobs on the copy: $ACTIVE"
if [[ "$ACTIVE" != 0 ]]; then
  confirm "Deactivate all cron jobs on the SCRATCH copy (cron.alter_job active := false)?" || abort "Crons must be off for the rehearsal."
  # postgres cannot UPDATE cron.job on Supabase; use the pg_cron functions (unschedule as fallback).
  sql "select cron.alter_job(jobid, active := false) from cron.job where active" >/dev/null \
    || sql "select cron.unschedule(jobid) from cron.job" >/dev/null \
    || abort "Could not deactivate cron jobs (alter_job and unschedule both failed)."
fi
[[ "$(sql 'select count(*) from cron.job where active')" == 0 ]] || abort "Cron jobs are still active. Stop and fix before continuing."
say "✓ No active cron jobs."
note "The prod wizard leaves crons untouched (AIO-83); this only applies to the copy."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Read-only prechecks"
sql "select 'marketing_assets rows / distinct ids / null ids: ' || count(*) || ' / ' || count(distinct id) || ' / ' || count(*) filter (where id is null) from public.marketing_assets" | tee "$LOG_DIR/precheck-assets.txt" | sed 's/^/    /'
sql "select 'marketing_assets pkey exists: ' || exists(select 1 from pg_constraint where conrelid='public.marketing_assets'::regclass and contype='p')" | sed 's/^/    /'
sql "select 'buckets present: ' || coalesce(string_agg(id, ', '), 'none') from storage.buckets where id in ('invoices','command-center-files','carmen-media')" | sed 's/^/    /'
sql "select 'lead INSERT policies: ' || coalesce(string_agg(policyname, ', '), 'none') from pg_policies where schemaname='public' and tablename='leads' and cmd='INSERT'" | sed 's/^/    /'
sql "select 'agent_tasks in realtime: ' || exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='agent_tasks')" | sed 's/^/    /'
sql "select jobid, jobname, active from cron.job order by jobid" | tee "$LOG_DIR/cron-before.txt" | sed 's/^/    /'
note "Crons are left untouched (AIO-83)."
confirm "Do these look as expected (ids unique, no nulls)?" || abort "Stopped at prechecks."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Has Production changed since the snapshot?"
if [[ -f "$SNAPSHOT_SCHEMA" ]]; then
  run schema-dump.txt npx supabase db dump --db-url "$DB_URL" -f "$LOG_DIR/current-schema.sql" || abort "Dump failed (Docker running?)."
  if diff -u "$SNAPSHOT_SCHEMA" "$LOG_DIR/current-schema.sql" > "$LOG_DIR/schema.diff"; then
    say "✓ Identical to the snapshot."
  else
    warn "Differs: $(grep -cE '^[+-][^+-]' "$LOG_DIR/schema.diff") changed lines (see $LOG_DIR/schema.diff)."
    confirm "Continue anyway (only if harmless)?" || abort "Stopped at the schema check."
  fi
else
  warn "$SNAPSHOT_SCHEMA missing; skipping the diff."
  confirm "Continue without it?" || abort "Stopped."
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Collect the old migration versions"
sql "select version from supabase_migrations.schema_migrations order by 1" | LC_ALL=C sort > "$LOG_DIR/remote-versions.txt"
ls supabase/migrations | grep -oE "^[0-9]{14}" | LC_ALL=C sort -u > "$LOG_DIR/local-versions.txt"
comm -23 "$LOG_DIR/remote-versions.txt" "$LOG_DIR/local-versions.txt" > "$LOG_DIR/old-versions.txt"
OLD_COUNT=$(wc -l < "$LOG_DIR/old-versions.txt" | tr -d ' ')
say "Remote-only versions to mark reverted: $OLD_COUNT"
say "First: $(head -1 "$LOG_DIR/old-versions.txt")   Last: $(tail -1 "$LOG_DIR/old-versions.txt")"
note "Backup of the full history list: $LOG_DIR/remote-versions.txt"
for v in $BASELINE $EXPECTED_PUSH; do
  ! grep -qx "$v" "$LOG_DIR/old-versions.txt" || abort "$v is in the revert list. Something is off."
done
(( OLD_COUNT > 0 )) || abort "Nothing to revert. Was the history already repaired?"
confirm "Does the count look right?" || abort "Stopped before touching the history."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Mark the old versions reverted"
say "Removes $OLD_COUNT rows from schema_migrations. Schema and data are untouched."
confirm "Mark $OLD_COUNT versions reverted on the REHEARSAL copy?" || abort "History not repaired."
# shellcheck disable=SC2046
run repair-reverted.txt npx supabase migration repair --db-url "$DB_URL" --status reverted $(cat "$LOG_DIR/old-versions.txt") \
  || abort "Repair (reverted) failed."
say "Rows left: $(sql 'select count(*) from supabase_migrations.schema_migrations')"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Mark the baseline applied"
say "Records only $BASELINE as applied; the catch-up is pushed for real next."
confirm "Mark $BASELINE applied on the REHEARSAL copy?" || abort "Stopped."
run repair-applied.txt npx supabase migration repair --db-url "$DB_URL" --status applied "$BASELINE" \
  || abort "Repair (applied) failed."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Dry-run push"
say "Expect exactly: $EXPECTED_PUSH"
run push-dry-run.txt npx supabase db push --db-url "$DB_URL" --dry-run || warn "Dry run exited non-zero."
PENDING=$(grep -oE '[0-9]{14}' "$LOG_DIR/push-dry-run.txt" | sort -u | tr '\n' ' ')
[[ "$PENDING" == "$EXPECTED_PUSH " ]] || abort "Pending: ${PENDING:-none}. Expected $EXPECTED_PUSH. Send the log to Claude."
say "✓ Pending list matches."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Push the catch-up and persona update"
warn "Applies $EXPECTED_PUSH to the REHEARSAL copy."
confirm "Run db push on the REHEARSAL copy?" || abort "Push not run."
run push.txt npx supabase db push --db-url "$DB_URL" || abort "Push failed. Send $LOG_DIR/push.txt to Claude."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Verify"
run migration-list.txt npx supabase migration list --db-url "$DB_URL" || true
sql "select 'marketing_assets pkey: ' || exists(select 1 from pg_constraint where conrelid='public.marketing_assets'::regclass and contype='p')" | sed 's/^/    /'
sql "select 'buckets: ' || string_agg(id, ', ') from storage.buckets where id in ('invoices','command-center-files','carmen-media')" | sed 's/^/    /'
sql "select 'lead INSERT policies: ' || string_agg(policyname || ' [' || coalesce(with_check,'') || ']', '; ') from pg_policies where schemaname='public' and tablename='leads' and cmd='INSERT'" | sed 's/^/    /'
say "Leads / clients: $(sql 'select (select count(*) from public.leads) || $$ / $$ || (select count(*) from public.clients)')"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Compare the result with Staging"
if [[ -f "$STAGING_SNAPSHOT" ]]; then
  run rehearsal-dump.txt npx supabase db dump --db-url "$DB_URL" -f "$LOG_DIR/rehearsal-schema.sql" || abort "Dump failed (Docker running?)."
  diff -u "$STAGING_SNAPSHOT" "$LOG_DIR/rehearsal-schema.sql" > "$LOG_DIR/staging-vs-rehearsal.diff" || true
  say "Lines that differ from Staging: $(grep -cE '^[+-][^+-]' "$LOG_DIR/staging-vs-rehearsal.diff")  (see $LOG_DIR/staging-vs-rehearsal.diff)"
  note "Some differences are expected (Staging-only reconcile, environment_sync). Anything touching policies or functions needs a look."
else
  warn "$STAGING_SNAPSHOT missing; skipping."
fi
say "Rehearsal complete. Send $LOG_DIR to Claude before the Production run."

finish
say "Logs: $LOG_DIR"
